const RATES_PER_1M = {
  &quot;gemini-4-hydrogen&quot;: { input: 1.50, cachedInput: 0.075, output: 7.50 },
  &quot;gemini-4-carbon&quot;:   { input: 2.00, cachedInput: 0.100, output: 10.00 }, // Intro rate thru Nov 30, 2026
